36	const (
37		uploadCheckpointInterval = 30 * time.Second
38	
39		// task info bucket
40		bucketTask = "task"
41		// task download data bucket
42		bucketSave = "save"
43		// task statistics snapshot bucket
44		bucketTaskStats = "task_stats"
45		// protocol-level shared client state bucket
46		bucketProtocolState = "protocol_state"
47		bucketProtocolJobs  = "protocol_jobs"
48		// downloader config bucket
49		bucketConfig = "config"
50		// downloader extension bucket
51		bucketExtension = "extension"
