541		rrId, err := gonanoid.New()
542		if err != nil {
543			return
544		}
545		ensureRequestRawURL(req)
546	
547		res, err := d.triggerOnResolve(req)
548		if err != nil {
549			return
550		}
551		if res != nil && len(res.Files) > 0 {
552			rr = &ResolveResult{
553				Res:                  res,
554				SuggestedDownloadDir: d.suggestedDownloadDir(res),
555			}
556			return
