660	// CreateWithOptions creates a resolved task using the submitted options, or the
661	// default download options when opts is nil.
662	func (d *Downloader) CreateWithOptions(rrId string, opts *base.Options) (taskId string, err error) {
663		d.fetcherMapLock.RLock()
664		fetcher, ok := d.fetcherCache[rrId]
665		d.fetcherMapLock.RUnlock()
666		if !ok {
667			return "", errors.New("invalid resource id")
668		}
669		if opts == nil {
670			opts = &base.Options{}
671		}
672		// The options of the caller decide the global default download directory,
673		// the task options are prepared later, when the task starts.
674		defaultPath, err := d.prepareDefaultPath(opts)
675		if err != nil {
676			return "", err
677		}
678		taskOpts, err := d.initOptions(opts.Clone(), fetcher.Meta().Req.URL)
679		if err != nil {
680			return "", err
681		}
682		if res := fetcher.Meta().Res; res != nil {
683			for _, index := range taskOpts.SelectFiles {
684				if index < 0 || index >= len(res.Files) {
685					return "", fmt.Errorf("invalid selected file index: %d", index)
686				}
687			}
688			taskOpts.InitSelectFiles(len(res.Files))
689		}
690		fetcher.Meta().Opts = taskOpts
691		if res := fetcher.Meta().Res; res != nil {
692			res.CalcSize(fetcher.Meta().Opts.SelectFiles)
693		}
694		// Resolve has no creation options. Publish a submitted HTTP estimate now
695		// while preserving any size already confirmed by the response.
696		if taskOpts.Size > 0 {
697			if err := fetcher.Patch(nil, &base.Options{Size: taskOpts.Size}); err != nil {
698				return "", err
699			}
700		}
701		defer func() {
702			d.fetcherMapLock.Lock()
703			delete(d.fetcherCache, rrId)
704			d.fetcherMapLock.Unlock()
705		}()
706		taskId, err = d.doCreate(fetcher, nil)
707		if err == nil {
708			d.persistDefaultPathBestEffort(defaultPath)
709		}
710		return
711	}
