713	// Patch modifies task-specific data based on the protocol.
714	// For HTTP protocol, it can modify Request info.
715	// For BT protocol, it can modify SelectFiles.
716	func (d *Downloader) Patch(id string, req *base.Request, opts *base.Options) error {
717		task := d.GetTask(id)
718		if task == nil {
719			return ErrTaskNotFound
720		}
721		if err := func() error {
722			task.lock.Lock()
723			defer task.lock.Unlock()
724	
725			// Restore fetcher if not loaded
726			if task.fetcher == nil {
727				err := func() error {
728					task.statusLock.Lock()
729					defer task.statusLock.Unlock()
730	
731					return d.restoreFetcher(task)
732				}()
733				if err != nil {
734					return err
735				}
736			}
737	
738			// Call the fetcher's Patch method
739			if err := task.fetcher.Patch(req, httpSizeOptions(opts, task.Protocol)); err != nil {
740				return err
741			}
742	
743			// Update task meta from fetcher and transfer any live Blob lease.
744			task.Meta = task.fetcher.Meta()
745			if err := d.syncBlobTaskLease(task); err != nil {
746				return err
747			}
748	
749			return d.saveTask(task)
750		}(); err != nil {
751			return err
752		}
753	
754		// Emit outside task.lock so listeners may safely call back into Patch/Pause.
755		d.emit(EventKeyProgress, task)
756	
757		return nil
758	}
