760	func (d *Downloader) Pause(filter *TaskFilter) (err error) {
761		if filter == nil || filter.IsEmpty() {
762			return d.pauseAll()
763		}
764	
765		filter.NotStatuses = []base.Status{base.DownloadStatusPause, base.DownloadStatusError, base.DownloadStatusDone}
766		pauseTasks := d.GetTasksByFilter(filter)
767		if len(pauseTasks) == 0 {
768			return ErrTaskNotFound
769		}
770	
771		for _, task := range pauseTasks {
772			if err = d.doPause(task); err != nil {
773				return
774			}
775		}
776		d.notifyRunning()
777	
778		return
779	}
