799	// Continue specific tasks, if continue tasks will exceed maxRunning, it needs pause some running tasks before that
800	func (d *Downloader) Continue(filter *TaskFilter) (err error) {
801		if filter == nil || filter.IsEmpty() {
802			return d.continueAll()
803		}
804	
805		filter.NotStatuses = []base.Status{base.DownloadStatusRunning, base.DownloadStatusDone}
806		continueTasks := d.GetTasksByFilter(filter)
807		if len(continueTasks) == 0 {
808			return ErrTaskNotFound
809		}
810	
811		realContinueTasks := make([]*Task, 0)
812		pausedTasks := make([]*Task, 0)
813		func() {
814			d.lock.Lock()
815			defer d.lock.Unlock()
816	
817			continueCount := len(continueTasks)
818			remainRunningCount := d.remainRunningCount()
819			needRunningCount := int(math.Min(float64(d.cfg.MaxRunning), float64(continueCount)))
820			needPauseCount := needRunningCount - remainRunningCount
821			if needPauseCount > 0 {
822				pausedCount := 0
823				for _, task := range d.tasks {
824					if task.Status == base.DownloadStatusRunning {
825						var queued bool
826						queued, err = d.doPauseForScheduling(task)
827						if err != nil {
828							return
829						}
830						if queued {
831							d.waitTasks = append(d.waitTasks, task)
832							pausedTasks = append(pausedTasks, task)
833							pausedCount++
834						}
835					}
836					if pausedCount == needPauseCount {
837						break
838					}
839				}
840			}
841	
842			for _, task := range continueTasks {
843				if len(realContinueTasks) < needRunningCount {
844					realContinueTasks = append(realContinueTasks, task)
845				} else {
846					task.Status = base.DownloadStatusWait
847					d.waitTasks = append(d.waitTasks, task)
848				}
849			}
850		}()
851		if err != nil {
852			return
853		}
854		// Scheduling pauses run while d.lock is held, but events must not: listeners
855		// are allowed to call back into Downloader methods that acquire d.lock.
856		for _, task := range pausedTasks {
857			d.emit(EventKeyPause, task)
858		}
859	
860		for _, task := range realContinueTasks {
861			if err = d.doStart(task); err != nil {
862				return
863			}
864		}
865	
866		return
867	}
868	
869	// continueAll continue all tasks but does not affect tasks already running
870	func (d *Downloader) continueAll() (err error) {
871		continuedTasks := make([]*Task, 0)
872	
873		func() {
874			d.lock.Lock()
875			defer d.lock.Unlock()
876			// calculate how many tasks can be continued, can't exceed maxRunning
877			remainCount := d.remainRunningCount()
878			for _, task := range d.tasks {
879				if task.Status != base.DownloadStatusRunning && task.Status != base.DownloadStatusDone {
880					if len(continuedTasks) < remainCount {
881						continuedTasks = append(continuedTasks, task)
882					} else {
883						task.Status = base.DownloadStatusWait
884						d.waitTasks = append(d.waitTasks, task)
885					}
886				}
887			}
888		}()
889	
890		for _, task := range continuedTasks {
891			if err = d.doStart(task); err != nil {
892				return
893			}
894		}
895	
896		return
897	}
898	
899	func (d *Downloader) ContinueBatch(filter *TaskFilter) (err error) {
