923	func (d *Downloader) Delete(filter *TaskFilter, force bool) (err error) {
924		if filter == nil || filter.IsEmpty() {
925			return d.deleteAll(force)
926		}
927	
928		deleteTasks := d.GetTasksByFilter(filter)
929		if len(deleteTasks) == 0 {
930			return
931		}
932	
933		deleteIds := make([]string, 0)
934		deleteTasksPtr := make([]*Task, 0)
935		for _, task := range deleteTasks {
936			deleteIds = append(deleteIds, task.ID)
937			deleteTasksPtr = append(deleteTasksPtr, task)
938		}
939		func() {
940			d.lock.Lock()
941			defer d.lock.Unlock()
942	
943			for _, id := range deleteIds {
944				for i, t := range d.tasks {
945					if t.ID == id {
946						d.tasks = append(d.tasks[:i], d.tasks[i+1:]...)
947						break
948					}
949				}
950				for i, t := range d.waitTasks {
951					if t.ID == id {
952						d.waitTasks = append(d.waitTasks[:i], d.waitTasks[i+1:]...)
953						break
954					}
955				}
956			}
957		}()
958	
959		for _, task := range deleteTasksPtr {
960			err = d.doDelete(task, force)
961			if err != nil {
962				return
963			}
964		}
965	
966		d.notifyRunning()
967		return
968	}
