970	func (d *Downloader) deleteAll(force bool) (err error) {
971		var deleteTasksTemp []*Task
972		func() {
973			d.lock.Lock()
974			defer d.lock.Unlock()
975	
976			for _, task := range d.tasks {
977				deleteTasksTemp = append(deleteTasksTemp, task)
978			}
979			d.tasks = make([]*Task, 0)
980			d.waitTasks = make([]*Task, 0)
981		}()
982	
983		for _, task := range deleteTasksTemp {
984			if err = d.doDelete(task, force); err != nil {
985				return
986			}
987		}
988		return
989	}
