991	func (d *Downloader) Stats(id string) (sr any, err error) {
992		task := d.GetTask(id)
993		if task == nil {
994			return sr, ErrTaskNotFound
995		}
996	
997		// A loaded fetcher is authoritative. Query it directly without restoring a
998		// paused fetcher from bucketSave: statistics reads must never consume or
999		// otherwise mutate download recovery state.
1000		task.lock.Lock()
1001		if task.fetcher != nil {
1002			status := d.taskStatus(task)
1003			live := status == base.DownloadStatusRunning || task.Uploading
1004			if captureErr := d.captureTaskStats(task, live, false); captureErr != nil {
1005				d.Logger.Warn().Err(captureErr).Msgf("capture task stats failed, task id: %s", task.ID)
1006			}
1007		}
1008		task.lock.Unlock()
1009	
1010		stats, err := d.loadTaskStats(task)
1011		if err != nil || stats == nil {
1012			return nil, err
1013		}
1014		return stats, nil
1015	}
1016	
1017	type storedTaskStats struct {
1018		Snapshot json.RawMessage `json:"snapshot"`
1019	}
1020	
1021	// captureTaskStats updates the task-level cache from a loaded fetcher and
1022	// persists only the stable Snapshot payload. Runtime telemetry is deliberately
1023	// discarded as soon as a task is no longer active.
1024	func (d *Downloader) captureTaskStats(task *Task, live, force bool) error {
1025		if task == nil || task.fetcher == nil {
1026			return nil
1027		}
1028		stats := task.fetcher.Stats()
1029		if stats == nil {
1030			return nil
1031		}
1032		if !live {
1033			stats = &fetcher.Stats{Snapshot: stats.Snapshot}
1034		}
1035	
1036		hasSnapshotUpdate := stats.Snapshot != nil
1037		var snapshot json.RawMessage
1038		if hasSnapshotUpdate {
1039			encoded, err := json.Marshal(stats.Snapshot)
1040			if err != nil {
1041				return err
1042			}
1043			if !bytes.Equal(encoded, []byte("null")) {
1044				snapshot = encoded
1045			} else {
1046				hasSnapshotUpdate = false
1047			}
1048		}
1049	
1050		task.statsLock.Lock()
1051		defer task.statsLock.Unlock()
1052		if err := d.loadStoredTaskStatsLocked(task); err != nil {
1053			return err
1054		}
1055		if !hasSnapshotUpdate {
1056			// A nil Snapshot means the protocol is temporarily unable to provide a
1057			// trustworthy stable view (for example while BT verifies restored
1058			// storage). Keep the previous Snapshot and refresh Runtime only.
1059			var previousSnapshot any
1060			if task.stats != nil {
1061				previousSnapshot = task.stats.Snapshot
1062			}
1063			if previousSnapshot == nil && len(task.statsSnapshot) > 0 {
1064				previousSnapshot = append(json.RawMessage(nil), task.statsSnapshot...)
1065			}
1066			if previousSnapshot == nil && stats.Runtime == nil {
1067				task.stats = nil
1068			} else {
1069				task.stats = &fetcher.Stats{Snapshot: previousSnapshot, Runtime: stats.Runtime}
1070			}
1071			return nil
1072		}
1073	
1074		task.stats = stats
1075		if !force && bytes.Equal(snapshot, task.statsSnapshot) {
1076			return nil
1077		}
1078	
1079		if err := d.storage.Put(bucketTaskStats, task.ID, &storedTaskStats{Snapshot: snapshot}); err != nil {
1080			return err
1081		}
1082		task.statsSnapshot = append(task.statsSnapshot[:0], snapshot...)
1083		return nil
1084	}
1085	
1086	// loadTaskStats lazily restores a task snapshot. The protocol payload stays as
1087	// json.RawMessage so Downloader remains independent from HTTP, BT, and ED2K
1088	// schemas and can return it without a second decode/encode cycle.
1089	func (d *Downloader) loadTaskStats(task *Task) (*fetcher.Stats, error) {
1090		task.statsLock.Lock()
1091		defer task.statsLock.Unlock()
1092		if err := d.loadStoredTaskStatsLocked(task); err != nil {
1093			return nil, err
1094		}
1095		return task.stats, nil
1096	}
1097	
1098	// loadStoredTaskStatsLocked initializes the cache from storage once. Caller
1099	// must hold statsLock. It is shared by reads and nil-Snapshot refreshes so the
1100	// latter can retain a trusted snapshot after process restart.
1101	func (d *Downloader) loadStoredTaskStatsLocked(task *Task) error {
1102		if task.statsLoaded {
1103			return nil
1104		}
1105		var stored storedTaskStats
1106		exists, err := d.storage.Get(bucketTaskStats, task.ID, &stored)
1107		if err != nil {
1108			return err
1109		}
1110		task.statsLoaded = true
1111		if !exists || len(stored.Snapshot) == 0 {
1112			return nil
1113		}
1114		task.statsSnapshot = append(json.RawMessage(nil), stored.Snapshot...)
1115		task.stats = &fetcher.Stats{
1116			Snapshot: append(json.RawMessage(nil), stored.Snapshot...),
1117		}
1118		return nil
1119	}
1120	
1121	// RuntimeStatus returns the small task snapshot used by high-frequency detail
1122	// polling. Reading task.lock before statusLock follows the same lock order as
1123	// pause and patch operations, while also keeping fetcher and resource metadata
1124	// stable while file progress is collected.
1125	func (d *Downloader) RuntimeStatus(id string) (*TaskRuntimeStatus, error) {
1126		task := d.GetTask(id)
1127		if task == nil {
1128			return nil, ErrTaskNotFound
1129		}
1130	
1131		task.lock.Lock()
1132		defer task.lock.Unlock()
1133		task.statusLock.Lock()
1134		defer task.statusLock.Unlock()
1135	
1136		result := &TaskRuntimeStatus{
1137			Status: task.Status,
1138			Files:  make([]FileRuntimeStatus, 0),
1139		}
1140		if task.Progress != nil {
1141			result.Used = task.Progress.Used
1142			result.Speed = task.Progress.Speed
1143			result.Downloaded = task.Progress.Downloaded
1144			result.UploadSpeed = task.Progress.UploadSpeed
1145			result.Uploaded = task.Progress.Uploaded
1146			result.ExtractStatus = task.Progress.ExtractStatus
1147			result.ExtractProgress = task.Progress.ExtractProgress
1148		}
1149		if task.Meta == nil || task.Meta.Res == nil {
1150			if task.Meta != nil && task.Meta.Opts != nil && task.Protocol == "http" {
1151				result.Total = max(0, task.Meta.Opts.Size)
1152			}
1153			return result, nil
1154		}
1155	
1156		result.Total = task.Meta.Res.Size
1157		if task.fetcher == nil {
1158			return result, nil
1159		}
1160	
1161		fileProgress := task.fetcher.Progress()
1162		var selectedFiles []int
1163		if task.Meta.Opts != nil {
1164			selectedFiles = task.Meta.Opts.SelectFiles
1165		}
1166		resourceFiles := task.Meta.Res.Files
1167		for progressIndex, downloaded := range fileProgress {
1168			resourceIndex := progressIndex
1169			if progressIndex < len(selectedFiles) {
1170				resourceIndex = selectedFiles[progressIndex]
1171			}
1172			if resourceIndex < 0 || resourceIndex >= len(resourceFiles) {
1173				continue
1174			}
1175			result.Files = append(result.Files, FileRuntimeStatus{
1176				Index:      resourceIndex,
1177				Size:       resourceFiles[resourceIndex].Size,
1178				Downloaded: downloaded,
1179			})
1180		}
1181		return result, nil
1182	}
