1184	func (d *Downloader) doDelete(task *Task, force bool) (err error) {
1185		defer d.releaseBlobTask(task)
1186		err = func() error {
1187			if err := d.storage.Delete(bucketTask, task.ID); err != nil {
1188				return err
1189			}
1190			if err := d.storage.Delete(bucketSave, task.ID); err != nil {
1191				return err
1192			}
1193			if err := d.storage.Delete(bucketTaskStats, task.ID); err != nil {
1194				return err
1195			}
1196	
1197			if task.fetcher != nil {
1198				if err := task.fetcher.Close(); err != nil {
1199					return err
1200				}
1201			}
1202			if force && task.Meta.Res != nil {
1203				if task.Meta.Res.Name != "" {
1204					if err := os.RemoveAll(task.Meta.FolderPath()); err != nil {
1205						return err
1206					}
1207				} else {
1208					if err := util.SafeRemove(task.Meta.SingleFilepath()); err != nil {
1209						return err
1210					}
1211				}
1212			}
1213			d.emit(EventKeyDelete, task)
1214			task = nil
1215			return nil
1216		}()
1217	
1218		if err != nil {
1219			d.Logger.Error().Stack().Err(err).Msgf("delete task failed, task id: %s", task.ID)
1220		}
1221		return
1222	}
