1224	func (d *Downloader) Close() error {
1225		if d.closed.Swap(true) {
1226			return nil
1227		}
1228		d.cancelBackground()
1229		d.waitForExtensionGit()
1230		if d.protocolJobs != nil {
1231			d.protocolJobs.close()
1232		}
1233		d.webviewProxyLock.Lock()
1234		if d.webviewProxy != nil {
1235			_ = d.webviewProxy.Close()
1236		}
1237		d.webviewProxyLock.Unlock()
1238	
1239		closeArr := []func() error{
1240			d.pauseAll,
1241		}
1242		for _, fm := range d.cfg.FetchManagers {
1243			closeArr = append(closeArr, fm.Close)
1244		}
1245		if d.blob != nil {
1246			closeArr = append(closeArr, d.blob.Close)
1247		}
1248		closeArr = append(closeArr, d.storage.Close, d.tempFiles.Close)
1249		// Make sure all resources are released, if had error, return the last error
1250		var lastErr error
1251		for i, close := range closeArr {
1252			if err := close(); err != nil {
1253				lastErr = err
1254				d.Logger.Error().Stack().Err(err).Msgf("downloader close failed, index: %d", i)
1255			}
1256		}
1257		return lastErr
1258	}
