1516	// wait task done
1517	func (d *Downloader) watch(task *Task) {
1518		if _, loaded := d.watchedTasks.LoadOrStore(task.ID, true); loaded {
1519			return
1520		}
1521		defer func() {
1522			d.watchedTasks.Delete(task.ID)
1523		}()
1524	
1525		// wait task upload done
1526		if task.Uploading {
1527			if uploader, ok := task.fetcher.(fetcher.Uploader); ok {
1528				go func() {
1529					err := uploader.WaitUpload()
1530					if err != nil {
1531						d.Logger.Warn().Err(err).Msgf("task wait upload failed, task id: %s", task.ID)
1532					}
1533	
1534					// Check if the task is deleted
1535					if d.GetTask(task.ID) != nil {
1536						task.Uploading = false
1537						d.storage.Put(bucketTask, task.ID, task.clone())
1538					}
1539				}()
1540			}
1541		}
1542	
1543		if d.taskStatus(task) == base.DownloadStatusDone {
1544			return
1545		}
1546	
1547		for {
1548			err := task.fetcher.Wait()
1549			if err != nil {
1550				status := d.taskStatus(task)
1551				if status == base.DownloadStatusPause || status == base.DownloadStatusWait {
1552					return
1553				}
1554				var sourceErr error
1555				if d.blob != nil && task.Meta != nil && task.Meta.Req != nil {
1556					sourceErr = d.blob.SourceError(task.Meta.Req.URL)
1557				}
1558				if sourceErr != nil {
1559					d.doOnBlobSourceError(task, sourceErr)
1560				} else {
1561					d.doOnError(task, err)
1562				}
1563				if d.taskStatus(task) == base.DownloadStatusRunning {
1564					continue
1565				}
1566				return
1567			}
1568	
1569			// When delete a not resolved task, need check if the task resource is nil
1570			if task.Meta.Res == nil || d.GetTask(task.ID) == nil {
1571				return
1572			}
1573			if d.blob != nil && task.Meta.Req != nil {
1574				if err := d.blob.SourceError(task.Meta.Req.URL); err != nil {
1575					d.doOnBlobSourceError(task, err)
1576					if d.taskStatus(task) == base.DownloadStatusRunning {
1577						continue
1578					}
1579					return
1580				}
1581			}
1582	
1583			if !d.markTaskDone(task) {
1584				return
1585			}
1586			if err := d.captureTaskStats(task, false, true); err != nil {
1587				d.Logger.Error().Stack().Err(err).Msgf("persist completed task stats failed, task id: %s", task.ID)
1588			}
1589			task.statusLock.Lock()
1590			snapshot := task.clone()
1591			task.statusLock.Unlock()
1592			d.storage.Put(bucketTask, task.ID, snapshot)
1593			d.emit(EventKeyDone, task)
1594			d.emit(EventKeyFinally, task, err)
1595			d.notifyRunning()
1596			d.releaseBlobTask(task)
1597			d.triggerOnDone(task)
1598			d.triggerWebhooks(WebhookEventDownloadDone, task, nil)
1599			d.triggerScripts(ScriptEventDownloadDone, task, nil)
1600	
1601			if e := postDownloadExtra(task.Meta); e != nil {
1602				downloadFilePath := task.Meta.SingleFilepath()
1603	
1604				cfg, _ := d.GetConfig()
1605	
1606				// Determine if auto-torrent is enabled (use global config if not explicitly set)
1607				autoTorrentEnabled := false
1608				if e.AutoTorrent != nil {
1609					autoTorrentEnabled = *e.AutoTorrent
1610				} else if cfg != nil && cfg.AutoTorrent != nil {
1611					autoTorrentEnabled = cfg.AutoTorrent.Enable
1612				}
1613	
1614				if autoTorrentEnabled && strings.HasSuffix(downloadFilePath, ".torrent") {
1615					// Determine if should delete torrent file after creating BT task
1616					shouldDelete := false
1617					if e.DeleteTorrentAfterDownload != nil {
1618						shouldDelete = *e.DeleteTorrentAfterDownload
1619					} else if cfg != nil && cfg.AutoTorrent != nil {
1620						shouldDelete = cfg.AutoTorrent.DeleteAfterDownload
1621					}
1622	
1623					go func() {
1624						_, err2 := d.CreateDirect(
1625							&base.Request{
1626								URL: downloadFilePath,
1627							},
1628							&base.Options{
1629								Path:        task.Meta.Opts.Path,
1630								SelectFiles: make([]int, 0),
1631							})
1632						if err2 != nil {
1633							d.Logger.Error().Err(err2).Msgf("auto create torrent task failed, task id: %s", task.ID)
1634							return
1635						}
1636	
1637						if shouldDelete {
1638							d.Delete(&TaskFilter{IDs: []string{task.ID}}, true)
1639						}
1640					}()
1641				}
1642	
1643				// Determine if auto-extract is enabled (use global config if not explicitly set)
1644				autoExtractEnabled := false
1645				if e.AutoExtract != nil {
1646					autoExtractEnabled = *e.AutoExtract
1647				} else if cfg != nil && cfg.Archive != nil {
1648					autoExtractEnabled = cfg.Archive.AutoExtract
1649				}
1650	
1651				// Auto-extract archive files using the extraction queue
1652				// This ensures only one extraction runs at a time to prevent resource exhaustion
1653				if autoExtractEnabled && isArchiveFile(downloadFilePath) {
1654					d.enqueueExtraction(task, downloadFilePath, e)
1655				}
1656			}
1657			return
1658		}
1659	}
1660	
1661	// postDownloadExtra returns the auto-torrent and auto-extract options of a
1662	// finished single-file task, in the HTTP options shape the extraction code
1663	// takes. FTP options carry the same fields. An FTP folder has no single file
1664	// to act on, so it gets nil, as does any other protocol.
1665	func postDownloadExtra(meta *fetcher.FetcherMeta) *http.OptsExtra {
1666		if meta == nil || meta.Opts == nil {
1667			return nil
1668		}
1669		switch e := meta.Opts.Extra.(type) {
1670		case *http.OptsExtra:
1671			return e
1672		case *ftp.OptsExtra:
1673			if meta.Res == nil || meta.Res.Name != "" || len(meta.Res.Files) != 1 {
1674				return nil
1675			}
1676			return &http.OptsExtra{
1677				Connections:                e.Connections,
1678				AutoTorrent:                e.AutoTorrent,
1679				DeleteTorrentAfterDownload: e.DeleteTorrentAfterDownload,
1680				AutoExtract:                e.AutoExtract,
1681				ArchivePassword:            e.ArchivePassword,
1682				DeleteAfterExtract:         e.DeleteAfterExtract,
1683			}
1684		}
1685		return nil
1686	}
