2139	// doPauseForScheduling physically pauses a running task without emitting while
2140	// the caller holds d.lock, then atomically moves it to the wait queue state.
2141	func (d *Downloader) doPauseForScheduling(task *Task) (bool, error) {
2142		generation, isReturn, err := d.preparePause(task)
2143		if err != nil || isReturn {
2144			return false, err
2145		}
2146		handled, err := d.runPauseHandler(task, generation, true)
2147		if err != nil || !handled {
2148			return false, err
2149		}
2150		task.statusLock.Lock()
2151		queued := task.Status == base.DownloadStatusPause && task.runGeneration == generation
2152		if queued {
2153			task.Status = base.DownloadStatusWait
2154		}
2155		task.statusLock.Unlock()
2156		return queued, nil
2157	}
