2161			if task.Status == base.DownloadStatusPause || task.Status == base.DownloadStatusDone || task.Status == base.DownloadStatusError {
2162				isReturn = true
2163				return
2164			}
2165	
2166			task.updateStatus(base.DownloadStatusPause)
2167			task.runGeneration++
2168			generation = task.runGeneration
2169			task.timer.Pause()
2170			return
2171		})
2172		if err != nil {
