2311	// enqueueExtraction adds an extraction job to the global extraction queue
2312	// This ensures only one extraction (or one multi-part archive extraction) runs at a time
2313	// to prevent resource exhaustion
2314	func (d *Downloader) enqueueExtraction(task *Task, downloadFilePath string, opts *http.OptsExtra) {
2315		partInfo := getArchivePartInfo(downloadFilePath)
2316	
2317		if partInfo.IsMultiPart {
2318			// For multi-part archives, handle specially
2319			d.enqueueMultiPartExtraction(task, downloadFilePath, partInfo, opts)
2320		} else {
2321			// For single archives, queue immediately
2322			d.enqueueSingleExtraction(task, downloadFilePath, opts)
2323		}
2324	}
