2346	// enqueueMultiPartExtraction handles queueing for multi-part archives
2347	// It ensures only ONE extraction job is queued when ALL parts are ready
2348	func (d *Downloader) enqueueMultiPartExtraction(task *Task, downloadFilePath string, partInfo ArchivePartInfo, opts *http.OptsExtra) {
2349		// Set multi-part info on the task
2350		task.Progress.MultiPartBaseName = partInfo.BaseName
2351		task.Progress.MultiPartNumber = partInfo.PartNumber
2352		task.Progress.MultiPartIsFirst = isFirstPart(downloadFilePath)
2353	
2354		// Check if all parts are downloaded
2355		destDir := task.Meta.Opts.Path
2356		allPartsReady, missingParts := d.checkMultiPartArchiveReady(downloadFilePath, destDir, partInfo)
2357	
2358		if !allPartsReady {
2359			// Not all parts are ready yet - just set status to waiting, don't queue anything
2360			task.Progress.ExtractStatus = ExtractStatusWaitingParts
2361			d.emit(EventKeyProgress, task)
2362			d.storage.Put(bucketTask, task.ID, task.clone())
2363			d.Logger.Info().Msgf("multi-part archive waiting for other parts, task id: %s, missing: %v", task.ID, missingParts)
2364			return
2365		}
2366	
2367		// All parts are ready! Atomically check if extraction has already been started/queued
2368		// and if not, mark this task as the one that will handle it
2369		// Use GetMultiPartArchiveBaseName to get the full path for comparison
2370		fullBaseName := GetMultiPartArchiveBaseName(downloadFilePath)
2371		shouldQueue := d.tryClaimMultiPartExtraction(task, fullBaseName)
2372	
2373		if !shouldQueue {
2374			// Another part already started/queued extraction, mark this task as done
2375			task.Progress.ExtractStatus = ExtractStatusDone
2376			task.Progress.ExtractProgress = 100
2377			d.emit(EventKeyProgress, task)
2378			d.storage.Put(bucketTask, task.ID, task.clone())
2379			d.Logger.Info().Msgf("multi-part archive extraction already handled by another part, task id: %s", task.ID)
2380			return
2381		}
2382	
2383		// This task claimed the extraction - status already set to queued in tryClaimMultiPartExtraction
2384		d.emit(EventKeyProgress, task)
2385		d.storage.Put(bucketTask, task.ID, task.clone())
2386	
2387		jobID := "multipart:" + fullBaseName
2388		d.Logger.Info().Msgf("multi-part extraction queued, task id: %s, job id: %s", task.ID, jobID)
2389	
2390		// Create and enqueue the extraction job
2391		job := NewExtractionJob(jobID, func() {
2392			d.performMultiPartExtraction(task, partInfo.FirstPartPath, destDir, opts)
2393		})
2394	
2395		go func() {
2396			GetExtractionQueue().Enqueue(job)
2397		}()
2398	}
2399	
2400	// checkMultiPartArchiveReady checks if all parts of a multi-part archive are downloaded
2401	// by examining task status rather than file existence
2402	func (d *Downloader) checkMultiPartArchiveReady(filePath string, destDir string, partInfo ArchivePartInfo) (bool, []string) {
2403		// Use task-based checking - find all tasks with the same MultiPartBaseName
2404		// and verify they are all in Done status
2405		baseName := GetMultiPartArchiveBaseName(filePath)
2406		if baseName == "" {
2407			return true, nil
2408		}
2409	
2410		return d.checkAllMultiPartTasksDone(baseName)
2411	}
2412	
2413	// checkAllMultiPartTasksDone checks if all tasks belonging to a multi-part archive are done
2414	func (d *Downloader) checkAllMultiPartTasksDone(baseName string) (bool, []string) {
2415		var notDoneParts []string
2416	
2417		d.lock.Lock()
2418		defer d.lock.Unlock()
2419	
2420		// Find all tasks that belong to this multi-part archive
2421		var relatedTasks []*Task
2422		for _, task := range d.tasks {
2423			taskBaseName := ""
2424			if task.Meta != nil && task.Meta.Res != nil && len(task.Meta.Res.Files) > 0 {
2425				taskBaseName = GetMultiPartArchiveBaseName(task.Meta.SingleFilepath())
2426			}
2427			if taskBaseName == baseName {
2428				relatedTasks = append(relatedTasks, task)
2429			}
2430		}
2431	
2432		// If we found no related tasks, we can't determine readiness
2433		if len(relatedTasks) == 0 {
2434			return false, []string{"no related tasks found for " + baseName}
2435		}
2436	
2437		// Check if all related tasks are done
2438		for _, task := range relatedTasks {
2439			if task.Status != base.DownloadStatusDone {
2440				notDoneParts = append(notDoneParts, task.Meta.SingleFilepath())
2441			}
2442		}
2443	
2444		return len(notDoneParts) == 0, notDoneParts
2445	}
2446	
2447	// tryClaimMultiPartExtraction atomically checks if extraction can be claimed for a multi-part archive
2448	// and if so, marks the task as queued. Returns true if this task should proceed with queueing.
2449	// This uses sync.Map.LoadOrStore for atomic claim to prevent race conditions.
2450	func (d *Downloader) tryClaimMultiPartExtraction(task *Task, baseName string) bool {
2451		// Use LoadOrStore for atomic claim - if another goroutine already stored a value, we get that value back
2452		_, alreadyClaimed := d.claimedExtractions.LoadOrStore(baseName, task.ID)
2453		if alreadyClaimed {
2454			return false // Another task already claimed it
2455		}
2456	
2457		// This task successfully claimed it
2458		task.Progress.ExtractStatus = ExtractStatusQueued
2459		return true
2460	}
2461	
2462	// releaseMultiPartExtractionClaim releases the extraction claim for a multi-part archive
2463	// This is primarily used for testing purposes
2464	func (d *Downloader) releaseMultiPartExtractionClaim(baseName string) {
2465		d.claimedExtractions.Delete(baseName)
2466	}
2467	
2468	// performExtraction performs extraction for a regular (non-multi-part) archive
2469	func (d *Downloader) performExtraction(task *Task, archivePath string, destDir string, opts *http.OptsExtra) {
2470		// Set extraction status to extracting
2471		task.Progress.ExtractStatus = ExtractStatusExtracting
2472		task.Progress.ExtractProgress = 0
2473		d.emit(EventKeyProgress, task)
2474		d.storage.Put(bucketTask, task.ID, task.clone())
2475	
2476		// Extract the archive
2477		extractErr := extractArchive(archivePath, destDir, opts.ArchivePassword, func(extractedFiles int, totalFiles int, progress int) {
2478			task.Progress.ExtractProgress = progress
2479			d.emit(EventKeyProgress, task)
2480		})
2481	
2482		d.handleExtractionResult(task, extractErr, []string{archivePath}, opts.DeleteAfterExtract)
2483	}
2484	
2485	// performMultiPartExtraction performs extraction for a multi-part archive
2486	func (d *Downloader) performMultiPartExtraction(task *Task, firstPartPath string, destDir string, opts *http.OptsExtra) {
2487		// Get the baseName for releasing the claim later
2488		fullBaseName := GetMultiPartArchiveBaseName(firstPartPath)
2489	
2490		// Set extraction status to extracting
2491		task.Progress.ExtractStatus = ExtractStatusExtracting
2492		task.Progress.ExtractProgress = 0
2493		d.emit(EventKeyProgress, task)
2494		d.storage.Put(bucketTask, task.ID, task.clone())
2495	
2496		d.Logger.Info().Msgf("starting multi-part archive extraction, first part: %s, task id: %s", firstPartPath, task.ID)
2497	
2498		// Extract the multi-part archive
2499		extractErr := extractMultiPartArchive(firstPartPath, destDir, opts.ArchivePassword, func(extractedFiles int, totalFiles int, progress int) {
2500			task.Progress.ExtractProgress = progress
2501			d.emit(EventKeyProgress, task)
2502		})
2503	
2504		// Collect all part files for potential deletion
2505		partFiles := d.collectMultiPartFiles(firstPartPath)
2506	
2507		d.handleExtractionResult(task, extractErr, partFiles, opts.DeleteAfterExtract)
2508	
2509		// Update status for all related multi-part tasks
2510		d.updateMultiPartTasksStatus(task, extractErr)
2511	
2512		// Release the claim so future downloads of the same archive can be extracted
2513		d.releaseMultiPartExtractionClaim(fullBaseName)
2514	}
2515	
2516	// collectMultiPartFiles collects all files belonging to a multi-part archive
2517	func (d *Downloader) collectMultiPartFiles(firstPartPath string) []string {
2518		var files []string
2519		partInfo := getArchivePartInfo(firstPartPath)
2520		dir := filepath.Dir(firstPartPath)
2521	
2522		switch {
2523		case strings.Contains(partInfo.Pattern, ".7z)"):
2524			// 7z: .7z.001, .7z.002, etc.
2525			files = d.collectSequentialFiles(dir, partInfo.BaseName, ".%03d")
2526		case strings.Contains(partInfo.Pattern, ".part"):
2527			// RAR new style
2528			files = d.collectRarNewStyleFiles(dir, partInfo.BaseName)
2529		case partInfo.Pattern == "rar-old-style" || strings.Contains(partInfo.Pattern, ".r("):
2530			// RAR old style
2531			files = d.collectRarOldStyleFiles(dir, partInfo.BaseName)
2532		case strings.Contains(partInfo.Pattern, ".zip)"):
2533			// ZIP multi-part
2534			files = d.collectSequentialFiles(dir, partInfo.BaseName, ".%03d")
2535		case strings.Contains(partInfo.Pattern, ".z("):
2536			// ZIP split
2537			files = d.collectZipSplitFiles(dir, partInfo.BaseName)
2538		}
2539	
2540		return files
2541	}
2542	
2543	// collectSequentialFiles collects sequential numbered files
2544	func (d *Downloader) collectSequentialFiles(dir, baseName, format string) []string {
2545		var files []string
2546		suffix := filepath.Ext(baseName)
2547		nameWithoutExt := strings.TrimSuffix(baseName, suffix)
2548		partNum := 1
2549	
2550		for {
2551			partPath := filepath.Join(dir, nameWithoutExt+suffix+fmt.Sprintf(format, partNum))
2552			if _, err := os.Stat(partPath); os.IsNotExist(err) {
2553				break
2554			}
2555			files = append(files, partPath)
2556			partNum++
2557		}
2558	
2559		return files
2560	}
2561	
2562	// collectRarNewStyleFiles collects RAR new style part files
2563	func (d *Downloader) collectRarNewStyleFiles(dir, baseName string) []string {
2564		var files []string
2565		partNum := 1
2566	
2567		for {
2568			singleDigitPath := filepath.Join(dir, baseName+fmt.Sprintf(".part%d.rar", partNum))
2569			doubleDigitPath := filepath.Join(dir, baseName+fmt.Sprintf(".part%02d.rar", partNum))
2570	
2571			if _, err := os.Stat(singleDigitPath); err == nil {
2572				files = append(files, singleDigitPath)
2573			} else if _, err := os.Stat(doubleDigitPath); err == nil {
2574				files = append(files, doubleDigitPath)
2575			} else {
2576				break
2577			}
2578			partNum++
2579		}
2580	
2581		return files
2582	}
2583	
2584	// collectRarOldStyleFiles collects RAR old style part files
2585	func (d *Downloader) collectRarOldStyleFiles(dir, baseName string) []string {
2586		var files []string
2587	
2588		// .rar file
2589		rarPath := filepath.Join(dir, baseName+".rar")
2590		if _, err := os.Stat(rarPath); err == nil {
2591			files = append(files, rarPath)
2592		}
2593	
2594		// .r00, .r01, etc.
2595		partNum := 0
2596		for {
2597			partPath := filepath.Join(dir, baseName+fmt.Sprintf(".r%02d", partNum))
2598			if _, err := os.Stat(partPath); os.IsNotExist(err) {
2599				break
2600			}
2601			files = append(files, partPath)
2602			partNum++
2603		}
2604	
2605		return files
2606	}
2607	
2608	// collectZipSplitFiles collects ZIP split files
2609	func (d *Downloader) collectZipSplitFiles(dir, baseName string) []string {
2610		var files []string
2611	
2612		// .z01, .z02, etc.
2613		partNum := 1
2614		for {
2615			partPath := filepath.Join(dir, baseName+fmt.Sprintf(".z%02d", partNum))
2616			if _, err := os.Stat(partPath); os.IsNotExist(err) {
2617				break
2618			}
2619			files = append(files, partPath)
2620			partNum++
2621		}
2622	
2623		// .zip file
2624		zipPath := filepath.Join(dir, baseName+".zip")
2625		if _, err := os.Stat(zipPath); err == nil {
2626			files = append(files, zipPath)
2627		}
2628	
2629		return files
2630	}
2631	
2632	// handleExtractionResult handles the result of an extraction operation
2633	func (d *Downloader) handleExtractionResult(task *Task, extractErr error, archiveFiles []string, deleteAfterExtract bool) {
2634		if extractErr != nil {
2635			d.Logger.Error().Err(extractErr).Msgf("auto extract archive failed, task id: %s", task.ID)
2636			task.Progress.ExtractStatus = ExtractStatusError
2637			d.emit(EventKeyProgress, task)
2638			d.storage.Put(bucketTask, task.ID, task.clone())
2639		} else {
2640			d.Logger.Info().Msgf("auto extract archive completed, task id: %s", task.ID)
2641			task.Progress.ExtractStatus = ExtractStatusDone
2642			task.Progress.ExtractProgress = 100
2643			d.emit(EventKeyProgress, task)
2644			d.storage.Put(bucketTask, task.ID, task.clone())
2645	
2646			// Delete archive files after successful extraction if enabled
2647			if deleteAfterExtract {
2648				for _, archiveFile := range archiveFiles {
2649					deleteErr := os.Remove(archiveFile)
2650					if deleteErr != nil {
2651						d.Logger.Error().Err(deleteErr).Msgf("delete archive after extraction failed: %s", archiveFile)
2652					} else {
2653						d.Logger.Info().Msgf("archive deleted after extraction: %s", archiveFile)
2654					}
2655				}
2656			}
2657		}
2658	}
2659	
2660	// updateMultiPartTasksStatus updates the extraction status for all tasks that belong to the same multi-part archive
2661	func (d *Downloader) updateMultiPartTasksStatus(sourceTask *Task, extractErr error) {
2662		if sourceTask.Progress.MultiPartBaseName == "" {
2663			return
2664		}
2665	
2666		status := ExtractStatusDone
2667		progress := 100
2668		if extractErr != nil {
2669			status = ExtractStatusError
2670			progress = 0
2671		}
2672	
2673		d.lock.Lock()
2674		defer d.lock.Unlock()
2675	
2676		for _, task := range d.tasks {
2677			if task.ID == sourceTask.ID {
2678				continue
2679			}
2680			if task.Progress.MultiPartBaseName == sourceTask.Progress.MultiPartBaseName {
2681				task.Progress.ExtractStatus = status
2682				task.Progress.ExtractProgress = progress
2683				d.emit(EventKeyProgress, task)
2684				d.storage.Put(bucketTask, task.ID, task.clone())
2685			}
2686		}
2687	}
