2692		task.statusLock = &sync.Mutex{}
2693		task.lock = &sync.Mutex{}
2694		task.statsLock = &sync.Mutex{}
2695		task.blobRefLock = &sync.Mutex{}
2696		task.speedArr = make([]int64, 0)
