705	func rangeFileHandle(writer http.ResponseWriter, request *http.Request, modifyEnd func(end int64) int64, iocpN func(file *os.File, n int64)) {
706		r := request.Header.Get("Range")
707	
708		// If no Range header, return full file with Accept-Ranges header
709		if r == "" {
710			// Open file first to ensure it exists
711			file, err := os.Open(BuildFile)
712			if err != nil {
713				writer.WriteHeader(500)
714				return
715			}
716			defer file.Close()
717	
718			writer.Header().Set("Content-Length", fmt.Sprintf("%d", BuildSize))
719			writer.Header().Set("Accept-Ranges", "bytes")
720			writer.WriteHeader(200)
721			(writer.(http.Flusher)).Flush()
722	
723			iocpN(file, BuildSize)
724			return
725		}
726	
727		// split range
728		s := strings.Split(r, "=")
729		if len(s) != 2 {
730			writer.WriteHeader(400)
731			return
732		}
733		s = strings.Split(s[1], "-")
734		if len(s) != 2 {
735			writer.WriteHeader(400)
736			return
737		}
738		start, err := strconv.ParseInt(s[0], 10, 64)
739		if err != nil {
740			writer.WriteHeader(400)
741			return
742		}
743		end := int64(BuildSize - 1)
744		if s[1] != "" {
745			end, err = strconv.ParseInt(s[1], 10, 64)
746			if err != nil {
747				writer.WriteHeader(400)
748				return
749			}
750		}
751		if start < 0 || end < 0 || start > end {
752			writer.WriteHeader(400)
753			return
754		}
755		if end >= BuildSize {
756			end = BuildSize - 1
757		}
758	
759		if modifyEnd != nil {
760			end = modifyEnd(end)
761		}
762	
763		// Open file before sending headers to ensure it exists
764		file, err := os.Open(BuildFile)
765		if err != nil {
766			writer.WriteHeader(500)
767			return
768		}
769		defer file.Close()
770		file.Seek(start, 0)
771	
772		writer.Header().Set("Content-Length", fmt.Sprintf("%d", end-start+1))
773		writer.Header().Set("Content-Range", fmt.Sprintf("bytes %d-%d/%d", start, end, BuildSize))
774		writer.Header().Set("Accept-Ranges", "bytes")
775		writer.WriteHeader(206)
776		(writer.(http.Flusher)).Flush()
777	
778		iocpN(file, end-start+1)
779	}
