781	// slowCopyN copies n bytes from src to dst, speed limit is bytes per second
782	func slowCopy(sl *shutdownListener, dst io.Writer, src io.Reader, delay int64) (written int64, err error) {
783		buf := make([]byte, 32*1024)
784		for {
785			if sl.isShutdown {
786				return 0, errors.New("server shutdown")
787			}
788			nr, er := src.Read(buf)
789			if nr > 0 {
790				nw, ew := dst.Write(buf[0:nr])
791				if nw > 0 {
792					written += int64(nw)
793				}
794				if ew != nil {
795					err = ew
796					break
797				}
798				if nr != nw {
799					err = io.ErrShortWrite
800					break
801				}
802			}
803			if er != nil {
804				if er != io.EOF {
805					err = er
806				}
807				break
808			}
809			if delay > 0 {
810				time.Sleep(time.Millisecond * time.Duration(delay))
811			}
812		}
813		return written, err
814	}
815	
816	func slowCopyN(sl *shutdownListener, dst io.Writer, src io.Reader, n int64, delay int64) (written int64, err error) {
817		written, err = slowCopy(sl, dst, io.LimitReader(src, n), delay)
818		if written == n {
819			return n, nil
820		}
821		if written < n && err == nil {
822			// src stopped early; must have been EOF.
823			err = io.EOF
824		}
825		return
826	}
827	
828	// slowCopyAfterDelay sleeps once before performing a normal copy to simulate a single timeout.
829	func slowCopyAfterDelay(sl *shutdownListener, dst io.Writer, src io.Reader, n int64, delay int64) (written int64, err error) {
830		if delay > 0 {
831			time.Sleep(time.Millisecond * time.Duration(delay))
832		}
833		return slowCopyN(sl, dst, src, n, 0)
834	}
