836	func startTestServer(serverHandle func(sl *shutdownListener) http.Handler) net.Listener {
837		listener, err := net.Listen("tcp", "127.0.0.1:0")
838		if err != nil {
839			panic(err)
840		}
841		file, err := os.Create(BuildFile)
842		if err != nil {
843			panic(err)
844		}
845		defer file.Close()
846		// Write random data
847		l := int64(8192)
848		buf := make([]byte, l)
849		size := int64(0)
850		for {
851			_, err := rand.Read(buf)
852			if err != nil {
853				panic(err)
854			}
855			if size+l >= BuildSize {
856				file.WriteAt(buf[0:BuildSize-size], size)
857				break
858			}
859			file.WriteAt(buf, size)
860			size += l
861		}
862		server := &http.Server{}
863		sl := &shutdownListener{
864			server:   server,
865			Listener: listener,
866		}
867		server.Handler = serverHandle(sl)
868		go server.Serve(listener)
869	
870		return sl
871	}
