923	// StartTestPatchURLServer creates a server with two endpoints:
924	// - /bad-url: always returns 404 (simulates a broken download link)
925	// - /good-url: returns the file successfully (simulates a working download link)
926	// This is used to test the Patch functionality where a failed download URL can be
927	// replaced with a working one.
928	func StartTestPatchURLServer() net.Listener {
929		return startTestServer(func(sl *shutdownListener) http.Handler {
930			mux := http.NewServeMux()
931			// Bad URL - always fails with 404
932			mux.HandleFunc("/bad-url", func(writer http.ResponseWriter, request *http.Request) {
933				writer.WriteHeader(404)
934				writer.Write([]byte("Not Found"))
935			})
936			// Good URL - returns the file successfully with range support
937			mux.HandleFunc("/good-url", func(writer http.ResponseWriter, request *http.Request) {
938				rangeFileHandle(
939					writer,
940					request,
941					nil,
942					func(file *os.File, n int64) {
943						io.CopyN(writer, file, n)
944					},
945				)
946			})
947			return mux
948		})
949	}
950	
951	// StartTestCookieExpiringServer creates a server that simulates cookie expiration during download.
952	// - First request (Resolve): accepts "session=old_token" and succeeds
953	// - Subsequent requests: "session=old_token" is expired (returns 401), only "session=new_token" works
954	// This is used to test the Patch functionality where a cookie expires mid-download,
955	// requiring the user to patch with a new cookie to resume.
956	func StartTestCookieExpiringServer() net.Listener {
957		var requestCount atomic.Int32
958	
959		return startTestServer(func(sl *shutdownListener) http.Handler {
960			mux := http.NewServeMux()
961			mux.HandleFunc("/"+BuildName, func(writer http.ResponseWriter, request *http.Request) {
962				reqNum := requestCount.Add(1)
963				cookie := request.Header.Get("Cookie")
964	
965				// First request (Resolve): accept old_token
966				if reqNum == 1 {
967					if !strings.Contains(cookie, "session=old_token") {
968						writer.WriteHeader(401)
969						writer.Write([]byte("Unauthorized: Invalid cookie"))
970						return
971					}
972					// Return file info for resolve (with range support)
973					rangeFileHandle(
974						writer,
975						request,
976						nil,
977						func(file *os.File, n int64) {
978							io.CopyN(writer, file, n)
979						},
980					)
981					return
982				}
983	
984				// Subsequent requests: old_token is expired, only new_token works
985				if strings.Contains(cookie, "session=new_token") {
986					// New token is valid - return the file with range support
987					rangeFileHandle(
988						writer,
989						request,
990						nil,
991						func(file *os.File, n int64) {
992							io.CopyN(writer, file, n)
993						},
994					)
995					return
996				}
997	
998				// Old token or invalid token - return 401
999				writer.WriteHeader(401)
1000				writer.Write([]byte("Unauthorized: Cookie expired"))
1001			})
1002			return mux
1003		})
1004	}
