414	// StartTestExpiringRedirectServer creates a server that simulates expiring redirect URLs.
415	// The original URL redirects to a temporary URL that expires after a specified number of requests.
416	// When the temporary URL expires (returns 403), the client should retry with the original URL
417	// to get a new redirect URL.
418	// Parameters:
419	//   - requestsBeforeExpire: number of requests the temporary URL accepts before expiring
420	//   - delayPerByte: optional delay per byte for slow transfer (use 0 for no delay)
421	func StartTestExpiringRedirectServer(requestsBeforeExpire int32, delayPerByte time.Duration) net.Listener {
422		var redirectVersion atomic.Int32
423		var requestCount atomic.Int32
424		redirectVersion.Store(1)
425	
426		return startTestServer(func(sl *shutdownListener) http.Handler {
427			return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
428				path := request.URL.Path
429	
430				// Original URL - redirects to current version of temporary URL
431				if path == "/"+BuildName {
432					// Reset request count when original URL is accessed
433					requestCount.Store(0)
434					// Redirect to versioned temporary URL
435					version := redirectVersion.Load()
436					redirectURL := fmt.Sprintf("/redirect-v%d/%s", version, BuildName)
437					http.Redirect(writer, request, redirectURL, http.StatusFound)
438					return
439				}
440	
441				// Temporary URL handler - matches /redirect-v{N}/... pattern
442				if strings.HasPrefix(path, "/redirect-v") {
443					// Check if the redirect has expired
444					count := requestCount.Add(1)
445					if count > requestsBeforeExpire {
446						// Redirect expired - increment version for next redirect
447						redirectVersion.Add(1)
448						writer.WriteHeader(403)
449						writer.Write([]byte("Redirect URL expired"))
450						return
451					}
452	
453					// Serve the file with range support
454					rangeFileHandle(
455						writer,
456						request,
457						nil,
458						func(file *os.File, n int64) {
459							if delayPerByte > 0 {
460								slowCopyNWithDelay(sl, writer, file, n, delayPerByte)
461							} else {
462								io.CopyN(writer, file, n)
463							}
464						},
465					)
466					return
467				}
468	
469				// Not found
470				writer.WriteHeader(404)
471			})
472		})
473	}
