493	// slowCopyNWithDelay copies n bytes from src to dst with a delay per byte
494	func slowCopyNWithDelay(sl *shutdownListener, dst io.Writer, src io.Reader, n int64, delayPerByte time.Duration) {
495		buf := make([]byte, 32*1024)
496		remaining := n
497		for remaining > 0 {
498			if sl.isShutdown {
499				return
500			}
501			toRead := int64(len(buf))
502			if toRead > remaining {
503				toRead = remaining
504			}
505			nr, er := src.Read(buf[:toRead])
506			if nr > 0 {
507				nw, ew := dst.Write(buf[0:nr])
508				if nw > 0 {
509					remaining -= int64(nw)
510					// Add delay based on bytes written
511					if delayPerByte > 0 {
512						time.Sleep(delayPerByte * time.Duration(nw))
513					}
514				}
515				if ew != nil {
516					break
517				}
518			}
519			if er != nil {
520				break
521			}
522		}
523	}
