579	// StartTestTemporary500Server creates a server that returns 500 for a duration, then recovers
580	// Uses slow transfer to ensure the file isn't fully downloaded during resolve phase
581	func StartTestTemporary500Server(errorDuration time.Duration) net.Listener {
582		startTime := time.Now()
583		var requestCount atomic.Int32
584	
585		return startTestServer(func(sl *shutdownListener) http.Handler {
586			mux := http.NewServeMux()
587			mux.HandleFunc("/"+BuildName, func(writer http.ResponseWriter, request *http.Request) {
588				reqNum := requestCount.Add(1)
589	
590				// First request (Resolve) succeeds with slow transfer to prevent full download
591				// Subsequent requests return 500 for the specified duration, then recover
592				if reqNum == 1 {
593					// Slow transfer for resolve: 50 microsecond per byte (~20MB/s)
594					// This ensures resolve doesn't complete the full 200MB file
595					rangeFileHandle(
596						writer,
597						request,
598						nil,
599						func(file *os.File, n int64) {
600							slowCopyNWithDelay(sl, writer, file, n, 50*time.Microsecond)
601						},
602					)
603					return
604				}
605	
606				// Subsequent requests: return 500 for errorDuration, then normal
607				if time.Since(startTime) < errorDuration {
608					writer.WriteHeader(500)
609					writer.Write([]byte("Internal Server Error"))
610					return
611				}
612	
613				rangeFileHandle(
614					writer,
615					request,
616					nil,
617					func(file *os.File, n int64) {
618						slowCopyN(sl, writer, file, n, 0)
619					},
620				)
621			})
622			return mux
623		})
624	}
