626	// StartTestFailThenRecoverServer creates a server that fails all connections initially,
627	// then recovers after a specified number of failed requests.
628	// This tests the retry functionality when calling Start() again after a download fails.
629	// Parameters:
630	//   - failedRequestsBeforeRecover: number of requests that will fail before server recovers
631	//
632	// Note: Uses 416 (Range Not Satisfiable) instead of 500 because 5xx errors are exempt
633	// from failure counting and will retry indefinitely. 416 is counted as a failure.
634	func StartTestFailThenRecoverServer(failedRequestsBeforeRecover int32) net.Listener {
635		var requestCount atomic.Int32
636	
637		return startTestServer(func(sl *shutdownListener) http.Handler {
638			mux := http.NewServeMux()
639			mux.HandleFunc("/"+BuildName, func(writer http.ResponseWriter, request *http.Request) {
640				reqNum := requestCount.Add(1)
641	
642				// First request (Resolve) always succeeds
643				if reqNum == 1 {
644					rangeFileHandle(
645						writer,
646						request,
647						nil,
648						func(file *os.File, n int64) {
649							io.CopyN(writer, file, n)
650						},
651					)
652					return
653				}
654	
655				// Subsequent requests fail until we've had enough failures
656				// Use 416 Range Not Satisfiable - this error is counted towards failure limit
657				if reqNum <= failedRequestsBeforeRecover+1 { // +1 because first request is resolve
658					writer.WriteHeader(416)
659					writer.Write([]byte("Range Not Satisfiable"))
660					return
661				}
662	
663				// After enough failures, server recovers
664				rangeFileHandle(
665					writer,
666					request,
667					nil,
668					func(file *os.File, n int64) {
669						io.CopyN(writer, file, n)
670					},
671				)
672			})
673			return mux
674		})
675	}
